import {pet,icons} from './character.js';
import {stages} from './logic.js';
const fmt=n=>n===null?'—':Math.round(n).toLocaleString('ko-KR');
export const roomItems=[['none','기본','headphones'],['cap','베레모','cap'],['flower','꽃핀','flower'],['scarf','머플러','scarf']];
export function roomScreen(d,s,ui,eventMarkup){
 const stage=ui.previewStage??d.stage;
 const mood=ui.previewMood!=='idle'?ui.previewMood:d.hungry?'hungry':'idle';
 const start=stages[d.stage].km,next=d.next?.km;
 const progress=d.distance===null?null:next?Math.max(0,Math.min(100,(d.distance-start)/(next-start)*100)):100;
 const hat=ui.tab==='home'?ui.previewHat:s.hat;
 const demoPose=ui.previewStage!==null||ui.previewMood!=='idle';
 return `<header class="room-header"><div>${icons.music}<h1>토토의 음악방</h1><span class="room-stage">${stages[stage].name}</span></div><div class="room-distance">함께 달린 거리 <strong>${fmt(d.distance)} <small>km</small></strong></div></header>
 <div class="room-layout"><section class="room-scene ${mood==='rain'?'rain-scene':''}" aria-label="토토의 픽셀 음악방"><img class="room-background" src="bungbung-assets/music-room.png" alt="턴테이블과 레코드, 체크 러그가 있는 민트색 픽셀 음악방"><div class="room-weather">${icons[mood==='rain'?'rain':'sun']}<span>${fmt(d.temp)}°</span></div>${demoPose?'<span class="pose-preview-label">디자인 미리보기</span>':''}<div class="scene-message">${ui.bubble||({hungry:'꼬르륵… 주유소에 들러주세요.',recovery:'냠냠, 다시 힘이 나요!',music:'지금 이 리듬, 좋아요.',rain:'비 오는 날엔 조금 더 여유롭게.'}[mood]||'오늘도 함께 달려서 좋았어!')}</div><button id="pet" class="scene-pet ${ui.pose==='joy'?'joy':ui.pose==='walking'?'walking':mood==='music'?'listening':'breathing'}" aria-label="토토 쓰다듬기">${pet(stage,mood,hat,d.temp)}</button>${mood==='rain'?'<div class="rain-lines" aria-hidden="true"></div>':''}${mood==='music'?'<div class="floating-notes" aria-hidden="true"><i>♪</i><i>♫</i></div>':''}<div class="level-dock"><span class="level-label">${icons.growth}<b>Lv.${d.stage}</b><span>${stages[d.stage].name}</span><small>${next?`${fmt(d.distance)} / ${fmt(next)} km`:'최고 성장 단계'}</small></span><div class="pixel-level" role="progressbar" aria-label="다음 성장까지의 진행도" ${progress===null?'':`aria-valuenow="${Math.round(progress)}"`} aria-valuemin="0" aria-valuemax="100"><i style="width:${progress??0}%"></i></div></div>${eventMarkup}</section><aside class="room-side">${panel(d,s,ui,stage)}</aside></div>
 <nav class="room-nav">${[['home','내 방','home'],['food','먹이','food'],['music','음악','music'],['shop','상점','shop'],['level','성장','growth']].map(([id,t,ic])=>`<button data-room-tab="${id}" class="${ui.tab===id?'selected':''}" aria-pressed="${ui.tab===id}">${icons[ic]}<span>${t}</span></button>`).join('')}</nav>`;
}
function panel(d,s,ui,stage){
 if(ui.tab==='home')return `<div class="side-heading"><h2>꾸미기</h2><span>MY CLOSET</span></div><div class="accessory-grid">${roomItems.map(([id,name,ic])=>`<button data-hat="${id}" class="accessory ${ui.previewHat===id?'selected':''}" aria-pressed="${ui.previewHat===id}">${icons[ic]}<span>${name}</span>${ui.previewHat===id?'<b>✓</b>':''}</button>`).join('')}</div><button class="room-primary" id="apply-look">적용하기</button><div class="room-subactions"><button id="walk">작은 산책</button><button id="note">오늘의 메모 ↗</button></div>`;
 if(ui.tab==='food')return `<div class="side-heading"><h2>토토의 식사</h2><span>CAR ENERGY</span></div><div class="food-art ${d.hungry?'empty':''}">${icons.food}</div><strong class="side-number">${fmt(d.range)} <small>km</small></strong><p>${d.range===null?'차량 정보를 기다리고 있어요.':d.hungry?'토토가 배고파요.':'지금은 든든해요.'}</p><div class="mini-meter"><i style="width:${d.range===null?0:Math.max(0,Math.min(100,d.range/620*100))}%"></i></div><p class="side-note">실제 주유가 토토의 식사예요.<br>현재는 모의 데이터로 표시해요.</p><button data-room-tab="home" class="room-secondary">내 방으로</button>`;
 if(ui.tab==='music')return `<div class="side-heading"><h2>작은 음악 시간</h2><span>TOTO'S PLAYLIST</span></div><div class="vinyl ${ui.previewMood==='music'?'playing':''}"><i></i></div><h3>느긋한 오후</h3><p>토토와 잠깐 쉬어가요.</p><button id="music-toggle" class="room-primary">${ui.previewMood==='music'?'모션 멈추기':'음악 듣는 모션 보기'}</button><p class="side-note">청소년 포즈 미리보기<br>음원 재생은 연결되지 않았어요.</p>`;
 if(ui.tab==='shop')return `<div class="side-heading"><h2>작은 소품 가게</h2><span>PREVIEW ONLY</span></div><div class="shop-card">${icons.star}<h3>별빛 브로치</h3><span class="room-stage">출시 준비 중</span></div><button data-hat="star" class="room-primary">착용 미리보기</button><p class="side-note">미리보기 전용 아이템이에요.<br>결제 기능은 없어요.</p><button data-room-tab="home" class="room-secondary">옷장으로 돌아가기</button>`;
 return `<div class="side-heading"><h2>함께 자라는 중</h2><span>GROWTH</span></div><div class="trait-summary">${icons.growth}<strong>Lv.${d.stage}</strong><span>${stages[d.stage].name} 토토</span></div><p>${d.next?`다음 성장까지 ${fmt(d.distance===null?null:Math.max(0,d.next.km-d.distance))} km`:'앞으로의 드라이브도 함께해요.'}</p><div class="stage-picks">${stages.slice(1).map((x,i)=>`<button data-preview-stage="${i+1}" class="${stage===i+1?'selected':''}">${pet(i+1)}<span>${x.name}</span></button>`).join('')}</div><small class="side-note">모습 미리보기 · 실제 성장에는 영향 없음</small><button data-page="album" class="room-secondary">성장 앨범 ↗</button><button data-page="badges" class="room-secondary">배지 도감 ↗</button>`;
}
